484	/// Validating BF16 checkpoint loader backed by pinned staging: every method
485	/// checks dtype and config-derived dimensions at the load boundary; payload
486	/// alignment is not required. Uploads run in [`Self::finish`], after every
487	/// tensor has been validated.
488	pub struct StagedWeightLoader<'a> {
489	    ctx: &'a DeviceContext,
490	    stager: WeightStager,
491	    shards: &'a [SafeTensors<'a>],
492	    weight_map: &'a HashMap<String, usize>,
493	    slots: Vec<Slot>,
494	    vec_slots: Vec<VecSlot>,
495	    pending: Vec<PendingUpload<'a>>,
496	    retained: Vec<Vec<bf16>>,
497	    finished: bool,
498	    failed: bool,
499	    alloc_ms: f64,
500	}
501	
502	impl<'a> StagedWeightLoader<'a> {
503	    pub fn new(
504	        ctx: &'a DeviceContext,
505	        shards: &'a [SafeTensors<'a>],
506	        weight_map: &'a HashMap<String, usize>,
507	    ) -> Result<Self> {
508	        Ok(Self {
509	            ctx,
510	            stager: WeightStager::new(ctx)?,
511	            shards,
512	            weight_map,
513	            slots: Vec::new(),
514	            vec_slots: Vec::new(),
515	            pending: Vec::new(),
516	            retained: Vec::new(),
517	            finished: false,
518	            failed: false,
519	            alloc_ms: 0.0,
520	        })
521	    }
522	
523	    fn ensure_recording(&self) -> Result<()> {
524	        anyhow::ensure!(
525	            !self.finished && !self.failed,
526	            "staged loader already finished"
527	        );
528	        Ok(())
529	    }
530	
531	    fn push_slot(&mut self, data: CudaSlice<bf16>, rows: usize, cols: usize) -> SlotId {
532	        self.slots.push(Slot {
533	            data: Some(data),
534	            rows,
535	            cols,
536	        });
537	        SlotId(self.slots.len() - 1)
538	    }
539	
540	    /// Executes every recorded upload; must run before [`Self::take`].
541	    pub fn finish(&mut self) -> Result<()> {
542	        anyhow::ensure!(
543	            !self.finished && !self.failed,
544	            "staged loader already finished"
545	        );
546	        // Poisoned until every upload lands; a failed finish cannot retry
547	        // vacuously over the drained op list.
548	        self.failed = true;
549	        let uploads = self.pending.len();
550	        let t_upload = std::time::Instant::now();
551	        if let Err(err) = self.execute_uploads() {
552	            // Soundness closes here, not in Drop (skippable via `mem::forget`):
553	            // no submitted copy may outlive this call unresolved.
554	            staging::drain_or_abort(&self.ctx.stream, "staged upload failure");
555	            self.retained.clear();
556	            return Err(err);
557	        }
558	        self.retained.clear();
559	        self.failed = false;
560	        self.finished = true;
561	        info!(
562	            "weight load: {} uploads, alloc_api_wall {:.0}ms, execute_and_drain_wall {:.0}ms",
563	            uploads,
564	            self.alloc_ms,
565	            t_upload.elapsed().as_secs_f64() * 1e3
566	        );
567	        Ok(())
568	    }
569	
570	    fn execute_uploads(&mut self) -> Result<()> {
571	        for op in std::mem::take(&mut self.pending) {
572	            match op {
573	                // SAFETY: the destination is owned by `self.slots` (`take`
574	                // refuses to hand it out before a successful finish) and the
575	                // range was validated by prepare/prepare_cols at record time.
576	                PendingUpload::Contiguous { src, dst_at } => unsafe {
577	                    self.stager.upload_at(src, dst_at)?;
578	                },
579	                PendingUpload::ColShard { src, plan } => unsafe {
580	                    self.stager.upload_cols_at(src, &plan)?;
581	                },
582	                // SAFETY: destination validated at record time; sources
583	                // outlive the drain (borrowed: shards; owned: retained first).
584	                PendingUpload::Vector { src, dst_at } => {
585	                    let bytes = match src {
586	                        Cow::Borrowed(borrowed) => bf16_bytes(borrowed),
587	                        Cow::Owned(owned) => {
588	                            self.retained.push(owned);
589	                            bf16_bytes(self.retained.last().expect("just pushed"))
590	                        }
591	                    };
592	                    unsafe {
593	                        memcpy_htod_async(dst_at, bytes, self.ctx.stream.cu_stream())
594	                            .map_err(|e| anyhow::anyhow!("vector upload failed: {e}"))?;
595	                    }
596	                }
597	            }
598	        }
599	        self.ctx.sync()
600	    }
601	
602	    /// Redeems a recorded matrix after a successful [`Self::finish`].
603	    pub fn take(&mut self, slot: SlotId) -> DeviceMatrix {
604	        assert!(self.finished, "take before successful finish");
605	        let slot = &mut self.slots[slot.0];
606	        DeviceMatrix {
607	            data: slot.data.take().expect("slot already taken"),
608	            rows: slot.rows,
609	            cols: slot.cols,
610	        }
611	    }
612	
613	    fn tensor_2d(&self, name: &str, rows: usize, cols: usize) -> Result<&'a [u8]> {
614	        let tensor = find_tensor(self.shards, self.weight_map, name)?;
615	        let shape = tensor.shape();
616	        anyhow::ensure!(
617	            shape.len() == 2,
618	            "Tensor '{name}' expected 2D, got shape {shape:?}"
619	        );
620	        anyhow::ensure!(
621	            shape[0] == rows && shape[1] == cols,
622	            "Tensor '{name}' has shape {shape:?}, config expects [{rows}, {cols}]"
623	        );
624	        tensor_bf16_bytes(&tensor, name)
625	    }
626	
627	    fn alloc_timed(&mut self, elems: usize, name: &str) -> Result<CudaSlice<bf16>> {
628	        let t = std::time::Instant::now();
629	        // SAFETY: overwritten by its recorded upload before `take` can
630	        // expose it.
631	        let data = unsafe { self.ctx.stream.alloc::<bf16>(elems) }
632	            .map_err(|e| anyhow::anyhow!("Alloc failed for '{name}': {e}"))?;
633	        self.alloc_ms += t.elapsed().as_secs_f64() * 1e3;
634	        Ok(data)
635	    }
636	
637	    pub fn matrix(&mut self, name: &str, rows: usize, cols: usize) -> Result<SlotId> {
638	        self.ensure_recording()?;
639	        let src = self.tensor_2d(name, rows, cols)?;
640	        let mut data = self.alloc_timed(rows * cols, name)?;
641	        let dst_at = staging::prepare(&self.ctx.stream, src, &mut data, 0)?;
642	        self.pending.push(PendingUpload::Contiguous { src, dst_at });
643	        Ok(self.push_slot(data, rows, cols))
644	    }
645	
646	    /// Row-concatenation of `parts`, each a validated row range of its
647	    /// source tensor; all sources must have exactly `cols` columns.
648	    pub fn fused_rows(&mut self, cols: usize, parts: &[FusedPart]) -> Result<SlotId> {
649	        self.ensure_recording()?;
650	        anyhow::ensure!(!parts.is_empty(), "fused load needs at least one part");
651	        let mut total_rows = 0usize;
652	        let mut srcs = Vec::with_capacity(parts.len());
653	        for part in parts {
654	            let name = part.name;
655	            let full = self.tensor_2d(name, part.src_rows, cols)?;
656	            anyhow::ensure!(
657	                part.row_offset
658	                    .checked_add(part.rows)
659	                    .is_some_and(|end| end <= part.src_rows),
660	                "row range out of bounds for '{name}': row_offset={} rows={} total_rows={}",
661	                part.row_offset,
662	                part.rows,
663	                part.src_rows
664	            );
665	            let elem = std::mem::size_of::<bf16>();
666	            srcs.push(
667	                &full[part.row_offset * cols * elem..(part.row_offset + part.rows) * cols * elem],
668	            );
669	            total_rows += part.rows;
670	        }
671	        let mut data = self.alloc_timed(total_rows * cols, parts[0].name)?;
672	        let mut dst_offset = 0;
673	        for src in srcs {
674	            let dst_at = staging::prepare(&self.ctx.stream, src, &mut data, dst_offset)?;
675	            self.pending.push(PendingUpload::Contiguous { src, dst_at });
676	            dst_offset += src.len() / std::mem::size_of::<bf16>();
677	        }
678	        Ok(self.push_slot(data, total_rows, cols))
679	    }
680	
681	    /// `take` columns starting at `col_offset` of a source tensor validated
682	    /// to exactly `src_rows` x `src_cols` before anything is allocated.
683	    pub fn col_shard(
684	        &mut self,
685	        name: &str,
686	        src_rows: usize,
687	        src_cols: usize,
688	        col_offset: usize,
689	        take: usize,
690	    ) -> Result<SlotId> {
691	        self.ensure_recording()?;
692	        let full = self.tensor_2d(name, src_rows, src_cols)?;
693	        anyhow::ensure!(
694	            col_offset
695	                .checked_add(take)
696	                .is_some_and(|end| end <= src_cols),
697	            "col range out of bounds for '{name}': col_offset={col_offset} take={take} total_cols={src_cols}"
698	        );
699	        let mut data = self.alloc_timed(src_rows * take, name)?;
700	        let plan = staging::prepare_cols(
701	            &self.ctx.stream,
702	            full,
703	            src_cols,
704	            col_offset,
705	            take,
706	            &mut data,
707	        )?;
708	        self.pending
709	            .push(PendingUpload::ColShard { src: full, plan });
710	        Ok(self.push_slot(data, src_rows, take))
711	    }
